style.css:
@-moz-document url-prefix("https://docs.google.com/spreadsheets") {
body, div, textarea, input, button, span {
    font-family: "Segoe UI", Roboto, "Open Sans", sans-serif !important;
  }

  /* General background and text */
  body {
    background-color: #121212 !important;
    color: #e0e0e0 !important;
  }

  /* Sheet grid background */
  .grid-container,
  .cell-input,
  .kix-grid {
    background-color: #1e1e1e !important;
  }

  /* Top bar (menu, toolbar) */
  .docs-titlebar,
  .goog-toolbar,
  .docs-material {
    background-color: #1a1a1a !important;
    border-bottom: 1px solid #333 !important;
  }

  /* Sheet tabs */
  .docs-sheet-tab {
    background-color: #2c2c2c !important;
    color: #ccc !important;
  }
  .docs-sheet-tab:hover {
    background-color: #3c3c3c !important;
    color: #fff !important;
  }
  .docs-sheet-tab-active {
    background-color: #4c4c4c !important;
    color: #ffffff !important;
  }

  /* Sidebar (e.g., Explore, Comments) */
  .docs-sidebar,
  .sidebar {
    background-color: #202020 !important;
    color: #ddd !important;
  }

  /* Scrollbars */
  ::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }
  ::-webkit-scrollbar-thumb {
    background: #444 !important;
    border-radius: 4px;
  }
  ::-webkit-scrollbar-track {
    background: #1a1a1a !important;
  }

  /* Selection highlight */
  .kix-selection-overlay {
    border: 2px solid #00bcd4 !important;
  }

  /* Fix for toolbar buttons */
  .goog-toolbar-button,
  .goog-toolbar-menu-button {
    background-color: #2b2b2b !important;
    color: #fff !important;
  }

  .goog-toolbar-button:hover,
  .goog-toolbar-menu-button:hover {
    background-color: #444 !important;
  }
}
